import clsx from 'clsx';
import React, { forwardRef } from 'react';
import { isElement } from 'react-is';

import { footerCSS } from './Footer.sty.js';
import type { DataTestId } from '../../../core/types/data-props.js';
import type { StylingProps } from '../../../core/types/styling-props.js';
import type { WithChildren } from '../../../core/types/with-children.js';
import { textStyleCSS } from '../../../styles/textStyle.sty.js';
import { footerSlotCss } from '../EmptyState.sty.js';

//#region Typings
// eslint-disable-next-line @typescript-eslint/no-empty-interface
export interface EmptyStateFooterProps
  extends WithChildren,
    StylingProps,
    DataTestId {}
//#endregion Typings

/**
 * Typeguard function that will check if a React.Node is a EmptyState.Footer
 * @internal
 */
export function _isEmptyStateFooter(
  child: React.ReactNode,
): child is React.ReactElement<EmptyStateFooterProps> {
  return isElement(child) && child.type === Footer;
}

/**
 * The footer slot for the EmptyState component.
 */
export const Footer = /* @__PURE__ */ forwardRef<
  HTMLElement,
  EmptyStateFooterProps
>((props, forwardedRef) => {
  const {
    children,
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId,
  } = props;

  return (
    <footer
      ref={forwardedRef}
      className={clsx([
        footerCSS,
        footerSlotCss,
        textStyleCSS({ textStyle: 'base' }),
        consumerClassName,
      ])}
      style={consumerStyle}
      data-testid={dataTestId}
    >
      {children}
    </footer>
  );
});

(Footer as typeof Footer & { displayName: string }).displayName =
  'EmptyState.Footer';
